//! Furniture in the shared field: the web's own geometry (`engine/assets/furniture`, GENERATED by
//! tools/engine-furniture.mjs from the web's buildFurnitureShape — `pnpm engine:furniture`, CI
//! `--check`), placed by the rules of packages/shared/src/furniture (footprint.ts `turn` /
//! `footprintCenter`, layout.ts `elevation`), coloured per part from the piece's palette.
//!
//! The layout is the server's (ABSOLUTE cells, so a field scroll never touches it); the app bakes it
//! into one vertex-coloured mesh whenever it or the window changes — not per frame.

use craftyap_net::protocol::Furniture;
use glam::{Mat4, Quat, Vec3};
use serde::Deserialize;
use std::collections::HashMap;
use std::sync::OnceLock;

const JSON: &str = include_str!("../../../assets/furniture/furniture.json");
const BIN: &[u8] = include_bytes!("../../../assets/furniture/furniture.bin");

#[derive(Deserialize)]
struct Catalog {
    #[serde(rename = "rugTop")]
    rug_top: f32,
    kinds: Vec<KindDef>,
}

#[derive(Deserialize)]
pub struct Shape {
    vertex: usize,
    vertices: usize,
    index: usize,
    indices: usize,
    /// Vertices per part, in parts order (each part has one colour).
    parts: Vec<usize>,
    /// Per variant: each part's colour (sRGB hex).
    colors: Vec<Vec<u32>>,
}

#[derive(Deserialize)]
pub struct KindDef {
    pub key: String,
    pub placement: String,
    /// w (local x), d (local z), h cells
    pub size: [i32; 3],
    pub surface: f32,
    closed: Shape,
    open: Option<Shape>,
}

struct Data {
    rug_top: f32,
    kinds: HashMap<String, KindDef>,
    positions: Vec<Vec3>,
    normals: Vec<Vec3>,
    indices: Vec<u32>,
}

fn data() -> Option<&'static Data> {
    static D: OnceLock<Option<Data>> = OnceLock::new();
    D.get_or_init(|| {
        let cat: Catalog = match serde_json::from_str(JSON) {
            Ok(c) => c,
            Err(e) => {
                log::error!("furniture.json: {e} (no furniture drawn)");
                return None;
            }
        };
        let verts: usize = cat.kinds.iter().flat_map(|k| [Some(&k.closed), k.open.as_ref()]).flatten().map(|s| s.vertices).sum();
        let idx: usize = cat.kinds.iter().flat_map(|k| [Some(&k.closed), k.open.as_ref()]).flatten().map(|s| s.indices).sum();
        if BIN.len() != (verts * 6 + idx) * 4 {
            log::error!("furniture.bin does not match furniture.json (no furniture drawn)");
            return None;
        }
        let f = |i: usize| f32::from_le_bytes([BIN[i * 4], BIN[i * 4 + 1], BIN[i * 4 + 2], BIN[i * 4 + 3]]);
        let positions = (0..verts).map(|v| Vec3::new(f(v * 3), f(v * 3 + 1), f(v * 3 + 2))).collect();
        let normals = (0..verts).map(|v| Vec3::new(f(verts * 3 + v * 3), f(verts * 3 + v * 3 + 1), f(verts * 3 + v * 3 + 2))).collect();
        let indices = (0..idx).map(|i| u32::from_le_bytes(BIN[(verts * 6 + i) * 4..(verts * 6 + i) * 4 + 4].try_into().unwrap_or([0; 4]))).collect();
        Some(Data { rug_top: cat.rug_top, kinds: cat.kinds.into_iter().map(|k| (k.key.clone(), k)).collect(), positions, normals, indices })
    })
    .as_ref()
}

/// One drawn furniture vertex: world position, normal, sRGB colour.
#[repr(C)]
#[derive(Clone, Copy, Debug, Default, bytemuck::Pod, bytemuck::Zeroable)]
pub struct FurnitureVertex {
    pub pos: [f32; 3],
    pub nrm: [f32; 3],
    pub color: [u8; 4],
}

/// footprint.ts `turn`: (x, z) → (z, −x) per quarter turn, as three turns an object about +y.
pub fn turn(x: f32, z: f32, rot: u8) -> (f32, f32) {
    let (mut a, mut b) = (x, z);
    for _ in 0..(rot & 3) {
        (a, b) = (b, -a);
    }
    (a + 0.0, b + 0.0)
}

/// Every cell a piece fills, as absolute cells.
fn cells(def: &KindDef, p: &Furniture) -> Vec<(i32, i32, i32)> {
    let mut out = Vec::new();
    for i in 0..def.size[0] {
        for j in 0..def.size[1] {
            let (ox, oz) = turn(i as f32, j as f32, p.turn);
            for k in 0..def.size[2] {
                out.push((p.x + ox as i32, p.y as i32 + k, p.z + oz as i32));
            }
        }
    }
    out
}

/// footprint.ts `footprintCenter`: where the model's origin goes from the anchor cell's corner.
pub fn footprint_center(size: [i32; 3], rot: u8) -> (f32, f32) {
    let (cx, cz) = turn((size[0] - 1) as f32 / 2.0, (size[1] - 1) as f32 / 2.0, rot);
    (cx + 0.5, cz + 0.5)
}

/// Every cell solid furniture fills, ABSOLUTE (layout.ts solidCells: floor pieces, open doors not).
pub fn solid_cells(layout: &[Furniture]) -> std::collections::HashSet<(i32, i32, i32)> {
    let Some(d) = data() else { return Default::default() };
    layout
        .iter()
        .filter(|p| p.open != Some(1))
        .filter_map(|p| d.kinds.get(&p.kind).filter(|k| k.placement == "floor").map(|k| cells(k, p)))
        .flatten()
        .collect()
}

/// The layout baked into one mesh, in GRID coordinates (absolute minus the window origin).
pub fn bake(layout: &[Furniture], origin_x: i32, origin_z: i32) -> Vec<FurnitureVertex> {
    let Some(d) = data() else { return Vec::new() };
    // which piece fills which cell, per layer (layout.ts `at`): floor pieces are the solid layer
    let mut solid: HashMap<(i32, i32, i32), &KindDef> = HashMap::new();
    let mut rug: HashMap<(i32, i32, i32), ()> = HashMap::new();
    for p in layout {
        let Some(def) = d.kinds.get(&p.kind) else { continue };
        match def.placement.as_str() {
            "floor" => cells(def, p).into_iter().for_each(|c| {
                solid.insert(c, def);
            }),
            "rug" => cells(def, p).into_iter().for_each(|c| {
                rug.insert(c, ());
            }),
            _ => {}
        }
    }
    let mut out = Vec::new();
    for p in layout {
        let Some(def) = d.kinds.get(&p.kind) else {
            log::warn!("furniture: unknown kind {} (a newer server?) skipped", p.kind);
            continue;
        };
        let open = p.open == Some(1);
        let shape = if open { def.open.as_ref().unwrap_or(&def.closed) } else { &def.closed };
        let colors = shape.colors.get(p.palette as usize).or(shape.colors.first());
        let Some(colors) = colors else { continue };
        // layout.ts `elevation`: a surface piece stands on its host's top, or on a rug's pile
        let at = (p.x, p.y as i32, p.z);
        let elevation = if def.placement == "surface" {
            match solid.get(&at) {
                Some(host) => host.surface,
                None if rug.contains_key(&at) => d.rug_top,
                None => 0.0,
            }
        } else {
            0.0
        };
        let (cx, cz) = footprint_center(def.size, p.turn);
        let place = Mat4::from_rotation_translation(
            Quat::from_rotation_y(p.turn as f32 * std::f32::consts::FRAC_PI_2),
            Vec3::new((p.x - origin_x) as f32 + cx, p.y as f32 + elevation, (p.z - origin_z) as f32 + cz),
        );
        // each vertex's colour from its part
        let mut part_of = Vec::with_capacity(shape.vertices);
        for (i, &n) in shape.parts.iter().enumerate() {
            part_of.extend(std::iter::repeat_n(i, n));
        }
        for &i in &d.indices[shape.index..shape.index + shape.indices] {
            let v = shape.vertex + i as usize;
            let local = i as usize;
            let hex = colors.get(*part_of.get(local).unwrap_or(&0)).copied().unwrap_or(0xff00ff);
            out.push(FurnitureVertex {
                pos: place.transform_point3(d.positions[v]).to_array(),
                nrm: place.transform_vector3(d.normals[v]).to_array(),
                color: [(hex >> 16) as u8, (hex >> 8) as u8, hex as u8, 255],
            });
        }
    }
    out
}

/// Every kind the app can draw (the export's), for checks.
#[cfg(test)]
fn kinds() -> Vec<String> {
    data().map(|d| d.kinds.keys().cloned().collect()).unwrap_or_default()
}

#[cfg(test)]
mod tests {
    use super::*;

    fn piece(kind: &str, x: i32, y: u8, z: i32, turn: u8) -> Furniture {
        Furniture { kind: kind.into(), x, y, z, turn, palette: 0, open: None }
    }

    #[test]
    fn the_export_reads_and_every_kind_bakes() {
        let all = kinds();
        assert!(all.len() >= 50, "{} kinds", all.len());
        for k in &all {
            let mesh = bake(&[piece(k, 0, 4, 0, 0)], 0, 0);
            assert!(!mesh.is_empty() && mesh.len().is_multiple_of(3), "{k}");
            assert!(mesh.iter().all(|v| v.pos.iter().chain(&v.nrm).all(|c| c.is_finite())), "{k}");
            // no magenta: every part colour resolved
            assert!(mesh.iter().all(|v| v.color != [255, 0, 255, 255]), "{k} has an unresolved colour");
        }
    }

    #[test]
    fn turning_matches_three_and_the_footprint() {
        assert_eq!(turn(1.0, 0.0, 1), (0.0, -1.0));
        assert_eq!(turn(0.0, 1.0, 1), (1.0, 0.0));
        assert_eq!(turn(1.0, 2.0, 4), (1.0, 2.0));
        // a 2 × 1 piece turned once covers (0, 0) and (0, −1): its centre lands between them
        assert_eq!(footprint_center([2, 1, 1], 0), (1.0, 0.5));
        assert_eq!(footprint_center([2, 1, 1], 1), (0.5, 0.0));
        // and the model stays inside its cells
        let d = data().unwrap();
        let (key, def) = d.kinds.iter().find(|(_, k)| k.size[0] == 2 && k.placement == "floor").unwrap();
        for rot in 0..4 {
            let mesh = bake(&[piece(key, 10, 4, 10, rot)], 0, 0);
            let cells = cells(def, &piece(key, 10, 4, 10, rot));
            let (x0, x1) = (cells.iter().map(|c| c.0).min().unwrap() as f32, cells.iter().map(|c| c.0).max().unwrap() as f32 + 1.0);
            let (z0, z1) = (cells.iter().map(|c| c.2).min().unwrap() as f32, cells.iter().map(|c| c.2).max().unwrap() as f32 + 1.0);
            assert!(mesh.iter().all(|v| v.pos[0] >= x0 - 0.05 && v.pos[0] <= x1 + 0.05 && v.pos[2] >= z0 - 0.05 && v.pos[2] <= z1 + 0.05), "{key} rot {rot} leaves its cells");
        }
    }

    #[test]
    fn surface_pieces_stand_on_their_host() {
        let d = data().unwrap();
        let (table, tdef) = d.kinds.iter().find(|(_, k)| k.placement == "floor" && k.surface > 0.3).unwrap();
        let (vase, _) = d.kinds.iter().find(|(_, k)| k.placement == "surface").unwrap();
        let alone = bake(&[piece(vase, 3, 4, 3, 0)], 0, 0);
        let on = bake(&[piece(table, 3, 4, 3, 0), piece(vase, 3, 4, 3, 0)], 0, 0);
        let low = |m: &[FurnitureVertex], from: usize| m[from..].iter().map(|v| v.pos[1]).fold(f32::MAX, f32::min);
        let table_len = bake(&[piece(table, 3, 4, 3, 0)], 0, 0).len();
        let lift = low(&on, table_len) - low(&alone, 0);
        assert!((lift - tdef.surface).abs() < 1e-4, "lifted {lift}, table top {}", tdef.surface);
    }

    #[test]
    fn solid_cells_are_floor_pieces_and_an_open_door_is_not() {
        let mut door = piece("door", 0, 4, 0, 0);
        let rug = piece("rug", 5, 4, 5, 0);
        let sofa = piece("sofa", 9, 4, 9, 0);
        let cells = solid_cells(&[door.clone(), rug, sofa]);
        assert!(cells.contains(&(0, 4, 0)) && cells.contains(&(0, 5, 0)), "a closed door, two tall");
        assert!(!cells.contains(&(5, 4, 5)), "a rug is walked on");
        assert!(cells.contains(&(9, 4, 9)) && cells.contains(&(10, 4, 9)), "a sofa, two wide");
        door.open = Some(1);
        assert!(!solid_cells(&[door]).contains(&(0, 4, 0)), "an open door lets you through");
    }

    #[test]
    fn the_window_origin_moves_the_mesh_and_odd_input_is_harmless() {
        let d = data().unwrap();
        let k = d.kinds.keys().next().unwrap();
        let a = bake(&[piece(k, 5, 4, 5, 0)], 0, 0);
        let b = bake(&[piece(k, 5, 4, 5, 0)], 16, -32);
        assert!((a[0].pos[0] - b[0].pos[0] - 16.0).abs() < 1e-4 && (a[0].pos[2] - b[0].pos[2] + 32.0).abs() < 1e-4);
        let weird = Furniture { kind: "rocket-ship".into(), x: 0, y: 0, z: 0, turn: 9, palette: 200, open: Some(1) };
        assert!(bake(&[weird], 0, 0).is_empty());
        let mut over = piece(k, 0, 4, 0, 7);
        over.palette = 99; // an out-of-range colour falls back to the first, never panics
        assert!(!bake(&[over], 0, 0).is_empty());
    }
}
